import backtrader as bt


class IntradayDeviationFromOpen(bt.Strategy):
    params = (
        ("deviation_bps", 50),
    )

    def __init__(self):
        self.order = None
        self.current_date = None
        self.opening_price = None
        self.traded_today = False
        self.broker.set_coc(True)

    def notify_order(self, order):
        if order.status in (
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        ):
            self.order = None

    def next(self):
        bar_datetime = self.data.datetime.datetime(0)
        bar_date = bar_datetime.date()

        if bar_date != self.current_date:
            self.current_date = bar_date
            self.opening_price = self.data.open[0]
            self.traded_today = False

        if bar_datetime.hour == 15 and bar_datetime.minute == 59:
            if self.position and self.order is None:
                self.order = self.close()
            return

        if self.position or self.order is not None or self.traded_today:
            return

        deviation = self.p.deviation_bps / 10000.0
        long_threshold = self.opening_price * (1.0 - deviation)
        short_threshold = self.opening_price * (1.0 + deviation)

        if self.data.close[0] < long_threshold:
            self.order = self.buy()
            self.traded_today = True
        elif self.data.close[0] > short_threshold:
            self.order = self.sell()
            self.traded_today = True
